create extension if not exists pgcrypto;

create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, name text, target_course text default 'Inteligência Artificial', exam_date date not null default '2026-10-18', plan_start date not null default '2026-08-27', created_at timestamptz not null default now());
create table if not exists public.subjects (id uuid primary key default gen_random_uuid(), name text not null unique, created_at timestamptz not null default now());
create table if not exists public.topics (id uuid primary key default gen_random_uuid(), subject_id uuid not null references public.subjects(id) on delete cascade, name text not null, parent_topic_id uuid references public.topics(id) on delete set null, difficulty int not null default 1 check (difficulty between 1 and 5), created_at timestamptz not null default now(), unique(subject_id,name));
create table if not exists public.study_days (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, study_date date not null, week_number int not null, day_number int not null, phase text not null, status text not null default 'planned' check(status in ('planned','in_progress','completed','skipped')), created_at timestamptz not null default now(), unique(user_id,study_date));
create table if not exists public.study_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, study_day_id uuid references public.study_days(id) on delete set null, topic_id uuid references public.topics(id) on delete set null, started_at timestamptz, ended_at timestamptz, duration_seconds int not null default 0, completed boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.questions (id uuid primary key default gen_random_uuid(), subject_id uuid references public.subjects(id), topic_id uuid references public.topics(id), difficulty int not null default 1 check(difficulty between 1 and 5), statement text not null, option_a text not null, option_b text not null, option_c text not null, option_d text not null, option_e text not null, correct_answer char(1) not null check(correct_answer in ('A','B','C','D','E')), explanation text not null, created_at timestamptz not null default now());
create table if not exists public.question_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, question_id uuid not null references public.questions(id) on delete cascade, selected_answer char(1) not null check(selected_answer in ('A','B','C','D','E')), is_correct boolean not null, time_seconds int, attempted_at timestamptz not null default now());
create table if not exists public.simulations (id uuid primary key default gen_random_uuid(), title text not null, description text, duration_minutes int not null default 180, question_count int not null default 30, created_at timestamptz not null default now());
create table if not exists public.simulation_questions (simulation_id uuid references public.simulations(id) on delete cascade, question_id uuid references public.questions(id) on delete cascade, position int not null, primary key(simulation_id,question_id), unique(simulation_id,position));
create table if not exists public.simulation_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, simulation_id uuid not null references public.simulations(id), started_at timestamptz not null default now(), finished_at timestamptz, score numeric, correct_count int default 0, total_count int default 0, status text not null default 'in_progress' check(status in ('in_progress','completed','abandoned')));
create table if not exists public.simulation_answers (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references public.simulation_attempts(id) on delete cascade, question_id uuid not null references public.questions(id), selected_answer char(1) check(selected_answer in ('A','B','C','D','E')), is_correct boolean, time_seconds int, marked_for_review boolean not null default false, unique(attempt_id,question_id));
create table if not exists public.essays (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, week_number int not null, prompt_date date not null, theme text not null, command text not null, support_texts jsonb not null default '[]', content text not null default '', status text not null default 'draft' check(status in ('draft','submitted','corrected')), submitted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.essay_corrections (id uuid primary key default gen_random_uuid(), essay_id uuid not null unique references public.essays(id) on delete cascade, score int check(score between 0 and 40), summary text not null, strengths jsonb not null default '[]', weaknesses jsonb not null default '[]', errors jsonb not null default '[]', rewrite_suggestions jsonb not null default '[]', improvement_plan jsonb not null default '[]', created_at timestamptz not null default now());
create table if not exists public.reviews (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, topic_id uuid not null references public.topics(id) on delete cascade, due_at timestamptz not null, interval_days int not null, attempts int not null default 0, last_correct boolean, completed_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.error_notebook (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, question_id uuid not null references public.questions(id) on delete cascade, attempt_id uuid not null references public.question_attempts(id) on delete cascade, error_count int not null default 1, last_error_at timestamptz not null default now(), unique(user_id,question_id));
create table if not exists public.user_progress (user_id uuid primary key references auth.users(id) on delete cascade, questions_answered int not null default 0, correct_answers int not null default 0, study_seconds bigint not null default 0, essays_completed int not null default 0, simulations_completed int not null default 0, xp int not null default 0, updated_at timestamptz not null default now());

alter table public.profiles enable row level security;
alter table public.study_days enable row level security;
alter table public.study_sessions enable row level security;
alter table public.question_attempts enable row level security;
alter table public.simulation_attempts enable row level security;
alter table public.simulation_answers enable row level security;
alter table public.essays enable row level security;
alter table public.essay_corrections enable row level security;
alter table public.reviews enable row level security;
alter table public.error_notebook enable row level security;
alter table public.user_progress enable row level security;

create policy "own profile" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "own study days" on public.study_days for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own sessions" on public.study_sessions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own question attempts" on public.question_attempts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own simulation attempts" on public.simulation_attempts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own simulation answers" on public.simulation_answers for all using(exists(select 1 from public.simulation_attempts a where a.id=attempt_id and a.user_id=auth.uid())) with check(exists(select 1 from public.simulation_attempts a where a.id=attempt_id and a.user_id=auth.uid()));
create policy "own essays" on public.essays for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own corrections" on public.essay_corrections for all using(exists(select 1 from public.essays e where e.id=essay_id and e.user_id=auth.uid())) with check(exists(select 1 from public.essays e where e.id=essay_id and e.user_id=auth.uid()));
create policy "own reviews" on public.reviews for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own errors" on public.error_notebook for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own progress" on public.user_progress for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
